border:1px solid #edf0f4;border-radius:11px}.pc3-file b{font-size:9px}.pc3-file small{font-size:8px;color:#98a2b3}.pc3-file>span{width:34px;height:34px;border-radius:9px;display:grid;place-items:center;background:#eef1ff;color:#304aca;font-size:8px;font-weight:900}.pc3-submit{display:flex;justify-content:space-between;align-items:center;background:#101828;color:#fff;border-radius:17px;padding:16px 18px}.pc3-submit strong,.pc3-submit span{display:block}.pc3-submit strong{font-size:11px}.pc3-submit span{font-size:8px;color:#c7cad1;margin-top:3px}.pc3-submit button{border:0;border-radius:11px;background:#fff;color:#101828;padding:11px 15px;font:inherit;font-size:10px;font-weight:900;cursor:pointer;display:flex;align-items:center;gap:6px}.pc3-alert{padding:12px;border-radius:11px;background:#fff0f0;color:#a33;margin-bottom:12px;font-size:9px}@media(max-width:700px){.pc3-head,.pc3-submit{display:block}.pc3-head .btn{display:inline-flex;margin-top:10px}.pc3-grid{grid-template-columns:1fr}.pc3-card{padding:16px}.pc3-submit button{margin-top:12px;width:100%;justify-content:center}}</style>@endpush
@push('scripts')<script>(()=>{const form=document.getElementById('productForm'),input=document.getElementById('fileInput'),zone=document.getElementById('dropzone'),list=document.getElementById('fileList'),ids=document.getElementById('uploadIds');let uploaded=[];const csrf='{{ csrf_token() }}';async function addFiles(files){for(const file of Array.from(files||[])){const row=document.createElement('div');row.className='pc3-file';row.innerHTML='<span>'+file.name.split('.').pop().toUpperCase()+'</span><div><b></b><small>در حال بررسی...</small></div><i>…</i>';row.querySelector('b').textContent=file.name;list.appendChild(row);try{if(!/\.(pdf|doc|docx)$/i.test(file.name)||file.size>209715200)throw Error('فقط PDF/DOC/DOCX و حداکثر ۲۰۰MB مجاز است.');const fd=new FormData();fd.append('file',file);const r=await fetch('{{ route('admin.products.uploads.store') }}',{method:'POST',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:fd});const d=await r.json();if(!r.ok)throw Error(d.message||'آپلود ناموفق بود');(d.files||[]).forEach(f=>uploaded.push(f.id));row.querySelector('small').textContent='آماده ثبت';row.querySelector('i').textContent='✓';render()}catch(e){row.querySelector('small').textContent=e.message;row.querySelector('i').textContent='!'}}}function render(){ids.innerHTML=uploaded.map(id=>'<input type="hidden" name="upload_ids[]" value="'+id+'">').join('')}input?.addEventListener('change',e=>addFiles(e.target.files));['dragenter','dragover'].forEach(x=>zone?.addEventListener(x,e=>{e.preventDefault();zone.classList.add('over')}));zone?.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('over');addFiles(e.dataTransfer.files)});form?.addEventListener('submit',e=>{if(!uploaded.length){e.preventDefault();alert('حداقل یک فایل محصول انتخاب کنید.')}})})();</script>@endpush